from collections import defaultdict,deque
from pathlib import Path
import hashlib,json,subprocess
root=Path.cwd();base=root/'build/mapping-proof';out=base/'named';sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
files=[base/'reference.json',base/'candidate.json',base/'cells.v',base/'inputs.json',Path(__file__).resolve()]
inputs={str(p.relative_to(root)):sha(p) for p in files}
models=[json.loads(p.read_text())['modules']['wasmetal_core'] for p in files[:2]]
drivers=[];primary=[]
for m in models:
 d={};primary.append({b for p in m['ports'].values() if p['direction']=='input' for b in p['bits']})
 for c in m['cells'].values():
  ins=tuple(b for p,v in c['connections'].items() if c['port_directions'][p]=='input' for b in v if isinstance(b,int))
  for port,v in c['connections'].items():
   if c['port_directions'][port]!='output':continue
   for b in v:
    if isinstance(b,int):assert b not in d;d[b]=ins
 drivers.append(d)
pairs={}
for name in sorted(models[0]['netnames'].keys()&models[1]['netnames'].keys()):
 if '$' in name or name.startswith('cut_'):continue
 a,b=[m['netnames'][name] for m in models]
 if a.get('hide_name') or b.get('hide_name') or len(a['bits'])!=len(b['bits']):continue
 for index,pair in enumerate(zip(a['bits'],b['bits'])):
  if all(isinstance(bit,int) and bit in drivers[i] and bit not in primary[i] for i,bit in enumerate(pair)):
   pairs.setdefault(pair,(name,index))
forward=defaultdict(set);backward=defaultdict(set)
for a,b in pairs:forward[a].add(b);backward[b].add(a)
pairs={p:n for p,n in pairs.items() if len(forward[p[0]])==len(backward[p[1]])==1}
print('Unambiguous internal signal pairs:',len(pairs),flush=True)
def dependencies(d,bit,cuts):
 result=set();seen=set();stack=list(d[bit])
 while stack:
  b=stack.pop()
  if b in cuts:result.add(cuts[b]);continue
  if b in seen:continue
  seen.add(b);stack.extend(d.get(b,()))
 return result
removed=0
while True:
 ordered=list(pairs);cut_maps=[{p[i]:k for k,p in enumerate(ordered)} for i in range(2)]
 deps={k:dependencies(drivers[0],p[0],cut_maps[0])|dependencies(drivers[1],p[1],cut_maps[1]) for k,p in enumerate(ordered)}
 users=defaultdict(set)
 for k,values in deps.items():
  for v in values:users[v].add(k)
 degrees={k:len(v) for k,v in deps.items()};ready=deque(k for k,v in degrees.items() if not v);topological=[]
 while ready:
  k=ready.popleft();topological.append(k)
  for v in users[k]:
   degrees[v]-=1
   if not degrees[v]:ready.append(v)
 if len(topological)==len(pairs):break
 bad={ordered[k] for k,v in degrees.items() if v};removed+=len(bad)
 pairs={p:n for p,n in pairs.items() if p not in bad}
 print('Removed conservative cyclic/dependent cuts:',len(bad),flush=True)
assert pairs,'no sound internal cuts remain'
plan={'cuts':[{'name':pairs[p][0],'bit':pairs[p][1],'reference':p[0],'candidate':p[1]} for p in ordered],
      'topological_order':topological,'joint_dependencies':{str(k):sorted(v) for k,v in deps.items()},'removed_for_cycles':removed}
(out/'cuts.json').write_text(json.dumps(plan,indent=2)+'\n');print('Acyclic internal cuts:',len(pairs),flush=True)
for side,label in enumerate(['reference','candidate']):
 m=models[side];next_bit=max([b for c in m['cells'].values() for v in c['connections'].values() for b in v if isinstance(b,int)]+list(primary[side]))+1
 replacements={p[side]:next_bit+k for k,p in enumerate(ordered)}
 # Rewrite consumers, while keeping every cut definition as a checked output.
 for c in m['cells'].values():
  for port,values in c['connections'].items():
   if c['port_directions'][port]=='input':c['connections'][port]=[replacements.get(b,b) for b in values]
 for k,p in enumerate(ordered):
  for prefix,direction,bits in [('internal_input','input',[replacements[p[side]]]),('internal_definition','output',[p[side]])]:
   name=f'{prefix}_{k:05}';assert name not in m['ports'];m['ports'][name]={'direction':direction,'bits':bits}
 # Only ports name the proof graph; remove unused aliases and their attributes.
 m['netnames']={}
 (out/f'{label}.json').write_text(json.dumps({'modules':{'wasmetal_core':m}}))
 script=f'read_json {out}/{label}.json\nread_verilog {base}/cells.v\nhierarchy -check -top wasmetal_core\nproc\nflatten\nopt\ntechmap\nopt\naigmap\nclean -purge\ncheck -assert\nwrite_json {out}/{label}-aig.json\nwrite_aiger -symbols {out}/{label}.aig\n'
 (out/f'{label}.ys').write_text(script)
 with (out/f'{label}.log').open('w') as f:subprocess.run([str(root/'.cache/tools/usr/bin/yosys'),'-Q','-T','-s',str(out/f'{label}.ys')],stdout=f,stderr=subprocess.STDOUT,check=True)
 aig=json.loads((out/f'{label}-aig.json').read_text())['modules']['wasmetal_core']
 assert all(b not in ('x','z') for p in aig['ports'].values() for b in p['bits'])
 for c in aig['cells'].values():
  assert c['type'] in ('$_AND_','$_NOT_')
  assert all(b not in ('x','z') for bs in c['connections'].values() for b in bs)
 print(label,'prepared',flush=True)
for name,digest in inputs.items():assert sha(root/name)==digest,name
(out/'inputs.json').write_text(json.dumps({'inputs':inputs,'cuts_sha256':sha(out/'cuts.json'),'acyclic_internal_cut_count':len(pairs)},indent=2)+'\n')
